"""Schema-validated finite-bag executor for the language in README.md."""
import operator

COMPARISONS = dict(eq=operator.eq, ne=operator.ne, lt=operator.lt,
                   le=operator.le, gt=operator.gt, ge=operator.ge)


def shape(value, keys, label):
    if not isinstance(value, dict) or set(value) != set(keys):
        raise ValueError(label + ' shape')


def single(value, label):
    if not isinstance(value, dict) or len(value) != 1:
        raise ValueError(label + ' shape')
    return next(iter(value.items()))


def field_type(field, schema):
    if not isinstance(field, str) or field not in schema:
        raise ValueError('unknown field: ' + repr(field))
    return schema[field]


def compatible(a, b):
    return a == b or 'null' in (a, b)


def expression_type(expr, schema):
    # 'null' is an untyped null literal, not the type of a nullable column.
    op, arg = single(expr, 'expression')
    if op == 'col':
        return field_type(arg, schema)
    if op == 'lit':
        if arg is None:
            return 'null'
        if type(arg) is int:
            return 'int'
        if type(arg) is str:
            return 'str'
        raise ValueError('literal type')
    if op in ('add', 'sub'):
        if not isinstance(arg, list) or len(arg) != 2:
            raise ValueError('arithmetic arity')
        types = [expression_type(e, schema) for e in arg]
        if any(t not in ('int', 'null') for t in types):
            raise ValueError('integer arithmetic')
        return 'int'
    raise ValueError('unknown expression')


def validate_predicate(pred, schema):
    op, arg = single(pred, 'predicate')
    if op == 'is_null':
        expression_type(arg, schema)
    elif op == 'not':
        validate_predicate(arg, schema)
    elif op in ('and', 'or'):
        if not isinstance(arg, list) or len(arg) < 2:
            raise ValueError('boolean arity')
        for child in arg:
            validate_predicate(child, schema)
    elif op in COMPARISONS:
        if not isinstance(arg, list) or len(arg) != 2:
            raise ValueError('comparison arity')
        a, b = [expression_type(e, schema) for e in arg]
        if not compatible(a, b):
            raise ValueError('comparison types')
    else:
        raise ValueError('unknown predicate')


def output_mapping(value, label):
    if not isinstance(value, dict) or any(not isinstance(k, str) for k in value):
        raise ValueError(label + ' names')


def infer_schema(tables, plan):
    """Validate every node, expression and reference even on empty inputs."""
    if not isinstance(plan, dict) or not isinstance(plan.get('op'), str):
        raise ValueError('plan shape')
    op = plan['op']
    if op == 'scan':
        shape(plan, ('op', 'table', 'as'), 'scan')
        alias = plan['as']
        if not isinstance(alias, str) or not alias or '.' in alias:
            raise ValueError('scan alias')
        name = plan['table']
        if not isinstance(name, str) or name not in tables:
            raise ValueError('unknown table')
        return {alias + '.' + k: t for k, t in tables[name]['columns'].items()}
    if op == 'filter':
        shape(plan, ('op', 'input', 'predicate'), 'filter')
        schema = infer_schema(tables, plan['input'])
        validate_predicate(plan['predicate'], schema)
        return schema
    if op == 'project':
        shape(plan, ('op', 'input', 'fields'), 'project')
        schema = infer_schema(tables, plan['input'])
        output_mapping(plan['fields'], 'project')
        return {k: expression_type(e, schema) for k, e in plan['fields'].items()}
    if op == 'join':
        shape(plan, ('op', 'kind', 'left', 'right', 'left_on', 'right_on'), 'join')
        if plan['kind'] not in ('inner', 'left'):
            raise ValueError('join kind')
        left = infer_schema(tables, plan['left'])
        right = infer_schema(tables, plan['right'])
        if left.keys() & right.keys():
            raise ValueError('overlapping join fields')
        a = field_type(plan['left_on'], left)
        b = field_type(plan['right_on'], right)
        if not compatible(a, b):
            raise ValueError('join key types')
        return {**left, **right}
    if op == 'group':
        shape(plan, ('op', 'input', 'keys', 'aggregates'), 'group')
        schema = infer_schema(tables, plan['input'])
        keys = plan['keys']
        if not isinstance(keys, list):
            raise ValueError('group keys')
        for key in keys:
            field_type(key, schema)
        if len(set(keys)) != len(keys):
            raise ValueError('duplicate group keys')
        output_mapping(plan['aggregates'], 'aggregate')
        if set(keys) & plan['aggregates'].keys():
            raise ValueError('aggregate name collides with group key')
        for agg in plan['aggregates'].values():
            if not isinstance(agg, dict):
                raise ValueError('aggregate shape')
            fn = agg.get('fn')
            if fn == 'count_all':
                shape(agg, ('fn',), 'count_all')
            elif fn in ('count', 'sum'):
                shape(agg, ('fn', 'expr'), 'aggregate')
                t = expression_type(agg['expr'], schema)
                if fn == 'sum' and t not in ('int', 'null'):
                    raise ValueError('sum requires integers')
            else:
                raise ValueError('unknown aggregate function')
        return {**{k: schema[k] for k in keys},
                **{k: 'int' for k in plan['aggregates']}}
    raise ValueError('unknown plan operator')


def validate_request(request):
    shape(request, ('tables', 'plan'), 'request')
    if not isinstance(request['tables'], dict):
        raise ValueError('tables shape')
    for name, table in request['tables'].items():
        if not isinstance(name, str) or not name:
            raise ValueError('table name')
        shape(table, ('columns', 'rows'), 'table')
        if not isinstance(table['columns'], dict) or not isinstance(table['rows'], list):
            raise ValueError('table shape')
        for key, t in table['columns'].items():
            if not isinstance(key, str) or not key or '.' in key or t not in ('int', 'str'):
                raise ValueError('column schema')
        for row in table['rows']:
            shape(row, table['columns'], 'row')
            for key, value in row.items():
                expected = int if table['columns'][key] == 'int' else str
                if value is not None and type(value) is not expected:
                    raise ValueError('row type')
    infer_schema(request['tables'], request['plan'])
    return request


def scalar(expr, row):
    op, arg = single(expr, 'expression')
    if op == 'col':
        return row[arg]
    if op == 'lit':
        if arg is not None and type(arg) not in (int, str):
            raise ValueError('literal type')
        return arg
    if op in ('add', 'sub'):
        if not isinstance(arg, list) or len(arg) != 2:
            raise ValueError('arithmetic arity')
        a, b = [scalar(e, row) for e in arg]
        if any(v is not None and type(v) is not int for v in (a, b)):
            raise ValueError('integer arithmetic')
        if a is None or b is None:
            return None
        return a + b if op == 'add' else a - b
    raise ValueError('unknown expression')


def truth(pred, row):
    op, arg = single(pred, 'predicate')
    if op == 'is_null':
        return scalar(arg, row) is None
    if op == 'not':
        value = truth(arg, row)
        return None if value is None else not value
    if op in ('and', 'or'):
        if not isinstance(arg, list) or len(arg) < 2:
            raise ValueError('boolean arity')
        values = [truth(p, row) for p in arg]
        if op == 'and':
            return False if False in values else (None if None in values else True)
        return True if True in values else (None if None in values else False)
    if op not in COMPARISONS or not isinstance(arg, list) or len(arg) != 2:
        raise ValueError('comparison')
    a, b = [scalar(e, row) for e in arg]
    if a is None or b is None:
        return None
    if type(a) is not type(b) or type(a) not in (int, str):
        raise ValueError('comparison types')
    return COMPARISONS[op](a, b)


def execute(tables, plan):
    """Return (rows, actual nested-loop candidate pair count)."""
    validate_request({'tables': tables, 'plan': plan})

    def walk(p):
        op = p['op']
        if op == 'scan':
            table = tables[p['table']]
            prefix = p['as'] + '.'
            schema = {prefix + k: t for k, t in table['columns'].items()}
            rows = [{prefix + k: v for k, v in row.items()} for row in table['rows']]
            return rows, schema, 0
        if op == 'join':
            left, lc, ln = walk(p['left'])
            right, rc, rn = walk(p['right'])
            rows, count = [], ln + rn
            null_right = dict.fromkeys(rc)
            for a in left:
                matched = False
                for b in right:
                    count += 1
                    x, y = a[p['left_on']], b[p['right_on']]
                    if x is not None and y is not None and x == y:
                        rows.append({**a, **b})
                        matched = True
                if not matched and p['kind'] == 'left':
                    rows.append({**a, **null_right})
            return rows, {**lc, **rc}, count
        rows, schema, count = walk(p['input'])
        if op == 'filter':
            return [r for r in rows if truth(p['predicate'], r) is True], schema, count
        if op == 'project':
            fields = p['fields']
            out_schema = {k: expression_type(e, schema) for k, e in fields.items()}
            return [{k: scalar(e, r) for k, e in fields.items()} for r in rows], out_schema, count
        # Each group retains every occurrence, including duplicate input rows.
        groups = {}
        for row in rows:
            key = tuple(row[k] for k in p['keys'])
            groups.setdefault(key, []).append(row)
        if not p['keys'] and not rows:
            groups[()] = []
        result = []
        for key, members in groups.items():
            row = dict(zip(p['keys'], key))
            for name, agg in p['aggregates'].items():
                if agg['fn'] == 'count_all':
                    row[name] = len(members)
                else:
                    values = [scalar(agg['expr'], r) for r in members]
                    values = [v for v in values if v is not None]
                    row[name] = (len(values) if agg['fn'] == 'count'
                                 else (sum(values) if values else None))
            result.append(row)
        out_schema = {**{k: schema[k] for k in p['keys']},
                      **{k: 'int' for k in p['aggregates']}}
        return result, out_schema, count

    rows, _, comparisons = walk(plan)
    return rows, comparisons

