"""Conservative, schema-independent filter pushdown for INNER JOINs."""
import copy


def references(node):
    """Collect columns without interpreting literals as expressions."""
    if isinstance(node, dict):
        if 'col' in node:
            return {node['col']}
        if 'lit' in node:
            return set()
        return set().union(*(references(v) for v in node.values()))
    if isinstance(node, list):
        return set().union(*(references(v) for v in node))
    return set()


def may_output(plan, field):
    """Conservative ownership without table schemas.

    Scan aliases describe possible fields; validation establishes existence.
    Requiring exclusive ownership prevents ambiguous alias guesses from moving
    predicates across a schema boundary.
    """
    op = plan['op']
    if op == 'scan':
        prefix = plan['as'] + '.'
        return field.startswith(prefix) and '.' not in field[len(prefix):]
    if op == 'filter':
        return may_output(plan['input'], field)
    if op == 'project':
        return field in plan['fields']
    if op == 'group':
        return field in plan['keys'] or field in plan['aggregates']
    if op == 'join':
        return may_output(plan['left'], field) or may_output(plan['right'], field)
    return True


def conjuncts(predicate):
    if set(predicate) == {'and'}:
        return [term for child in predicate['and'] for term in conjuncts(child)]
    return [predicate]


def place(plan, predicate):
    if plan['op'] == 'filter':
        plan['input'] = place(plan['input'], predicate)
        return plan
    if plan['op'] == 'join' and plan['kind'] == 'inner':
        fields = references(predicate)
        for side, other in (('left', 'right'), ('right', 'left')):
            if fields and all(may_output(plan[side], f) and
                              not may_output(plan[other], f) for f in fields):
                plan[side] = place(plan[side], predicate)
                return plan
    return {'op': 'filter', 'input': plan, 'predicate': predicate}


def optimize(plan):
    """Return an independent plan, preserving the caller's input.

    A conjunction survives filtering iff every conjunct is true, including under
    three-valued logic. OR/NOT remain intact. LEFT JOIN, project and group are
    barriers; optimization still visits their input subplans.
    """
    def walk(node):
        op = node['op']
        if op == 'join':
            node['left'] = walk(node['left'])
            node['right'] = walk(node['right'])
        elif op in ('filter', 'project', 'group'):
            node['input'] = walk(node['input'])
            if op == 'filter':
                result = node['input']
                for term in conjuncts(node['predicate']):
                    result = place(result, term)
                return result
        return node

    return walk(copy.deepcopy(plan))

